            print(f"[MOLIT Capture] Found options for size '{size_limit}': {options_found}")
            if not options_found:
                print(f"[MOLIT Capture] No area options found for '{size_limit}' in attempt {attempt}.")
                continue
            # 각 옵션별 최고가 비교
            best_opt = None
            highest_price = -1
            for opt in options_found:
                val = opt['value']
                txt = opt['text']
                print(f"[MOLIT Capture] Checking option: {txt} (val: {val})")
                # 옵션 변경 스크립트 실행
                change_opt_script = f"""
                    var sel = document.querySelector("#dtlAreaS");
                    if (!sel || sel.options.length <= 1) {{
                        var allSelects = document.querySelectorAll("select");
                        sel = null;
                        for (var i = allSelects.length - 1; i >= 0; i--) {{
                            var s = allSelects[i];
                            if (s.options.length > 1 && s.id !== "srhSidoCodeS" && s.id !== "srhSignguCodeS" && s.id !== "srhEmdCodeS") {{
                                var hasDecimal = false;
                                var hasSizeLimit = false;
                                for (var j = 0; j < s.options.length; j++) {{
                                    var optText = s.options[j].text;
                                    if (optText.indexOf(".") !== -1) hasDecimal = true;
                                    if (optText.indexOf("{size_limit}") !== -1) hasSizeLimit = true;
                                }}
                                if (hasDecimal && hasSizeLimit) {{ sel = s; break; }}
                            }}
                        }}
                    }}
                    if (sel) {{
                        sel.value = "{val}";
                        if (typeof jQuery !== 'undefined') {{
                            jQuery(sel).val("{val}").trigger('change');
                        }} else {{
                            sel.dispatchEvent(new Event('change'));
                        }}
                        return "done";
                    }}
                    return "not_found";
