                driver.execute_script(change_opt_script)
                time.sleep(2.0) # 데이터 로딩 대기
                # 해당 옵션 데이터 테이블에서 최고 거래금액 산출
                get_price_script = """
                    var tables = document.querySelectorAll("#dtlList table");
                    var maxAmount = 0;
                    tables.forEach(function(table) {
                        var headerCells = Array.from(table.querySelectorAll("th"));
                        var priceColIdx = -1;
                        for (var idx = 0; idx < headerCells.length; idx++) {
                            var headerText = headerCells[idx].innerText.trim();
                            if (headerText.indexOf("거래금액") !== -1 || headerText.indexOf("금액") !== -1) {
                                priceColIdx = idx;
                                break;
                            }
                        }
                        if (priceColIdx === -1) priceColIdx = 5;
                        var rows = Array.from(table.querySelectorAll("tr"));
                        var tbodyRows = rows.filter(function(row) {
                            return row.parentNode.tagName.toLowerCase() === 'tbody';
                        });
                        var dataRows = [];
                        tbodyRows.forEach(function(row) {
                            var cells = row.querySelectorAll("td, th");
                            if (cells.length > 3) {
                                var firstCellText = cells[0].innerText.trim();
                                if (!firstCellText.startsWith("전용면적") && !firstCellText.startsWith("중개사") && !firstCellText.startsWith("계약년월") && firstCellText.indexOf("월") === -1) {
                                    dataRows.push(row);
                                }
                            }
                        });
                        for (var i = 0; i < dataRows.length; i += 2) {
                            var mainRow = dataRows[i];
                            if (!mainRow) continue;
                            var cells = mainRow.querySelectorAll("td, th");
                            if (cells.length > priceColIdx && cells[priceColIdx]) {
                                var priceText = cells[priceColIdx].innerText.trim().replace(/,/g, '');
                                var val = parseInt(priceText, 10);
                                if (!isNaN(val) && val > maxAmount) {
                                    maxAmount = val;
                                }
                            }
                        }
