                    return maxAmount;
                """
                max_price = driver.execute_script(get_price_script)
                print(f"[MOLIT Capture] Max price for option '{txt}': {max_price} 만원")
                if max_price > highest_price:
                    highest_price = max_price
                    best_opt = opt
            # 최종 최고가가 발견된 경우
            if best_opt and highest_price > 0:
                print(f"[MOLIT Capture] Best option selected: {best_opt['text']} with highest price {highest_price} 만원")
                selected_option_val = best_opt['value']
                selected_option_text = best_opt['text']
                has_data = True
                break
            else:
                # 데이터가 없는 경우(모든 옵션이 0)
                if options_found:
